def transform(grid):
    g=[r[:] for r in grid]
    n=len(g); m=len(g[0])
    pts=[(r,c,g[r][c]) for r in range(n) for c in range(m) if g[r][c]]
    # Marker 1 creates a horizontal 5-ray to the right; other markers pairwise
    # create horizontal/vertical 5 links and diagonal 4 extensions.
    ones=[(r,c) for r,c,v in pts if v==1]
    for r,c in ones:
        for j in range(c+1,m):
            if g[r][j]==0: g[r][j]=5
    # Other points: draw a cross through the midpoint of each separated pair.
    for i,(r,c,v) in enumerate(pts):
        if v==1: continue
        for rr,cc,w in pts[i+1:]:
            if w==1: continue
            if r==rr:
                for j in range(min(c,cc)+1,max(c,cc)):
                    if g[r][j]==0:g[r][j]=5
            elif c==cc:
                for j in range(min(r,rr)+1,max(r,rr)):
                    if g[j][c]==0:g[j][c]=5
    return g
