def transform(grid):
    g = [row[:] for row in grid]
    n, m = len(g), len(g[0])
    shifts = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    markers = [(r, c, g[r][c]) for r in range(n) for c in range(m) if g[r][c]]
    for r, c, v in markers:
        dr, dc = shifts[v]
        rr, cc = r + dr, c + dc
        # The colored marker is copied at its fixed translated position; a 5 line
        # fills the intervening cells in the source row or column.
        if dr == 0:
            for x in range(min(c, cc) + 1, max(c, cc)):
                if g[r][x] == 0:
                    g[r][x] = 5
        elif dc == 0:
            for y in range(min(r, rr) + 1, max(r, rr)):
                if g[y][c] == 0:
                    g[y][c] = 5
        if 0 <= rr < n and 0 <= cc < m and g[rr][cc] == 0:
            g[rr][cc] = v
    # 2, 3 and 6 produce diagonal 4 trails below-left of the translated marker.
    for r, c, v in markers:
        if v in (2, 3, 6):
            dr, dc = shifts[v]
            y, x = r + dr + 1, c + dc - 1
            while 0 <= y < n and 0 <= x < m:
                if g[y][x] == 0:
                    g[y][x] = 4
                y += 1
                x -= 1
    return g
