def transform(grid):
    g=[row[:] for row in grid]
    n,m=len(g),len(g[0])
    pts=[(r,c,g[r][c]) for r in range(n) for c in range(m) if g[r][c]]
    for r,c,v in pts:
        if v==1:
            rr,cc=r-1,c+2
            if 0<=rr<n and 0<=cc<m:g[rr][cc]=1
            for x in range(c+1,min(c+2,m)):
                if g[r][x]==0:g[r][x]=5
        elif v==2:
            cc=c-4
            if cc>=0:
                g[r][cc]=2
                for x in range(cc+1,c):
                    if g[r][x]==0:g[r][x]=5
        elif v==3:
            rr=r+3
            if rr<n:
                g[rr][c]=3
                for y in range(r+1,rr):
                    if g[y][c]==0:g[y][c]=5
                y,x=rr,c-1
                while y<n and x>=0:
                    if g[y][x]==0:g[y][x]=4
                    y+=1;x-=1
        elif v==6:
            rr=r-6
            if rr>=0:
                g[rr][c]=6
                for y in range(rr+1,r):
                    if g[y][c]==0:g[y][c]=5
            if any(w==2 for _,_,w in pts):
                y,x=r-1,c-1
                while y<n and x>=0:
                    if g[y][x]==0:g[y][x]=4
                    y+=1;x-=1
    return g
