def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c]]
    for r, c, color in markers:
        if color == 1:
            rr, cc = r - 1, c + 2
            if 0 <= rr < h and 0 <= cc < w:
                g[rr][cc] = 1
            for x in range(c + 1, cc):
                if 0 <= x < w and g[r][x] == 0:
                    g[r][x] = 5
        elif color == 2:
            cc = c - 4
            if cc >= 0:
                g[r][cc] = 2
                for x in range(cc + 1, c):
                    if g[r][x] == 0:
                        g[r][x] = 5
                y, x = r + 1, cc + 1
                while y < h and x >= 0:
                    if g[y][x] == 0:
                        g[y][x] = 4
                    y += 1
                    x -= 1
        elif color == 3:
            rr = r + 3
            if rr < h:
                g[rr][c] = 3
                for y in range(r + 1, rr):
                    if g[y][c] == 0:
                        g[y][c] = 5
        elif color == 6:
            rr = r - 6
            if rr >= 0:
                g[rr][c] = 6
                for y in range(rr + 1, r):
                    if g[y][c] == 0:
                        g[y][c] = 5
    return g
