def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    markers = [(r, c, out[r][c]) for r in range(h) for c in range(w) if out[r][c]]
    for r, c, color in markers:
        if color == 1:
            # Copy one up and two right; bridge toward the copied marker.
            rr, cc = r - 1, c + 2
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 1
            for x in range(c + 1, min(c + 3, w)):
                if out[r][x] == 0:
                    out[r][x] = 5
        elif color == 2:
            # Reflect four cells to the left, joining the pair with 5s.
            cc = c - 4
            if cc >= 0:
                out[r][cc] = 2
                for x in range(cc + 1, c):
                    if out[r][x] == 0:
                        out[r][x] = 5
        elif color == 3:
            # Copy three rows downward, with a 5 connector.
            rr = r + 3
            if rr < h:
                out[rr][c] = 3
                for y in range(r + 1, rr):
                    if out[y][c] == 0:
                        out[y][c] = 5
        elif color == 6:
            # Copy six rows upward, with a 5 connector.
            rr = r - 6
            if rr >= 0:
                out[rr][c] = 6
                for y in range(rr + 1, r):
                    if out[y][c] == 0:
                        out[y][c] = 5
    return out
